30		plus8NowUTC := utc(2026, 12, 31, 23, 30)
31		if !plus8Now.UTC().Equal(plus8NowUTC) {
32			t.Fatalf("test setup: %v is not %v in UTC", plus8Now, plus8NowUTC)
33		}
34		if plus8Now.Year() != 2027 || plus8Now.Month() != time.January {
35			t.Fatalf("test setup: wall clock should already show January 2027, got %v", plus8Now)
36		}
