41		if !r.Cancelled || !r.Cancellation.EndAt.Equal(wantEndJan) {
42			t.Fatalf("plus8 cancel = %+v, want created with end %v", r, wantEndJan)
43		}
44		// 同一当前时刻用纯 UTC 表示，另一份订阅的取消结果必须相同。
45		clk.t = plus8NowUTC
46		r = mustCancel(t, s, "plus8-utc")
47		if !r.Cancelled || !r.Cancellation.EndAt.Equal(wantEndJan) {
48			t.Fatalf("utc-representation cancel = %+v, want created with end %v", r, wantEndJan)
49		}
50	
51		// 首次登记后查询：仍显示订阅有效，展示相同终止时刻与原套餐条件。
52		st, err := s.Status("plus8")
53		if err != nil {
54			t.Fatal(err)
55		}
56		if !st.Subscribed || st.ScheduledEnd == nil || !st.ScheduledEnd.Equal(wantEndJan) {
57			t.Fatalf("status while cancelling = %+v, want subscribed with end %v", st, wantEndJan)
58		}
59		if st.CurrentTerms != wantTerms || st.PendingChange != nil {
60			t.Fatalf("terms/pending while cancelling: cur=%+v pending=%+v, want %+v",
61				st.CurrentTerms, st.PendingChange, wantTerms)
62		}
63	
64		// 情形二：当前时刻本地钟面 2026-12-31 19:30（UTC-5），本地还停在 2026 年
65		// 12 月，实际已是 UTC 2027-01-01 00:30。终止时刻应取 UTC 1 月的下一月
66		// 月初：2027-02-01 00:00 UTC，不能按本地 12 月少算一个月。
67		minus5Now := time.Date(2026, time.December, 31, 19, 30, 0, 0, zoneMinus5)
68		minus5NowUTC := utc(2027, 1, 1, 0, 30)
69		if !minus5Now.UTC().Equal(minus5NowUTC) {
70			t.Fatalf("test setup: %v is not %v in UTC", minus5Now, minus5NowUTC)
71		}
72		if minus5Now.Year() != 2026 || minus5Now.Month() != time.December {
73			t.Fatalf("test setup: wall clock should still show December 2026, got %v", minus5Now)
74		}
75		wantEndFeb := utc(2027, 2, 1, 0, 0)
76	
77		clk.t = minus5Now
78		r = mustCancel(t, s, "minus5")
79		if !r.Cancelled || !r.Cancellation.EndAt.Equal(wantEndFeb) {
80			t.Fatalf("minus5 cancel = %+v, want created with end %v", r, wantEndFeb)
81		}
82		// 同一当前时刻用纯 UTC 表示，结果相同。
83		clk.t = minus5NowUTC
84		r = mustCancel(t, s, "minus5-utc")
85		if !r.Cancelled || !r.Cancellation.EndAt.Equal(wantEndFeb) {
86			t.Fatalf("utc-representation cancel = %+v, want created with end %v", r, wantEndFeb)
87		}
88		st, err = s.Status("minus5")
89		if err != nil {
90			t.Fatal(err)
91		}
92		if !st.Subscribed || st.ScheduledEnd == nil || !st.ScheduledEnd.Equal(wantEndFeb) ||
93			st.CurrentTerms != wantTerms {
94			t.Fatalf("minus5 status while cancelling = %+v, want subscribed with end %v and terms %+v",
95				st, wantEndFeb, wantTerms)
96		}
97	}
98	
99	// TestCancelEndBoundaryNanosecondStatusAndUsage 锁定终止瞬间的纳秒级边界：
100	// 终止前最后一纳秒查询仍有效、事件仍归十二月且可接收；恰到达终止瞬间，状态
101	// 查询直接显示无有效订阅、当前套餐为零值、不再展示终止安排（不依赖先上报
102	// 用量或生成账单），恰在该瞬间的新事件返回 ErrEventBeforeSubscription。
103	// 终止瞬间换任何时区表达，上述结果不变。
104	func TestCancelEndBoundaryNanosecondStatusAndUsage(t *testing.T) {
105		s, clk := newTestService(utc(2026, 12, 15, 12, 0))
106		mustPlan(t, s, planDef("p", 1000, 10, 5, 0))
107		wantTerms := PlanTerms{PlanID: "p", MonthlyFee: 1000, IncludedUnits: 10, OveragePrice: 5}
108		mustAccount(t, s, "u")
109		mustSubscribe(t, s, "u", "p", utc(2026, 12, 1, 0, 0))
110		// quiet 从不上报用量、从不出账：状态翻转必须由状态查询直接体现。
111		mustAccount(t, s, "quiet")
112		mustSubscribe(t, s, "quiet", "p", utc(2026, 12, 1, 0, 0))
113	
114		r := mustCancel(t, s, "u")
115		end := r.Cancellation.EndAt // 2027-01-01 00:00:00 UTC
116		if !end.Equal(utc(2027, 1, 1, 0, 0)) {
117			t.Fatalf("test setup: end = %v, want 2027-01-01 00:00 UTC", end)
118		}
119		if r2 := mustCancel(t, s, "quiet"); !r2.Cancellation.EndAt.Equal(end) {
120			t.Fatalf("test setup: quiet end = %v, want %v", r2.Cancellation.EndAt, end)
121		}
122	
123		// 终止前的十二月用量：先在 12 月 10 日累计 5。
124		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "mid", At: utc(2026, 12, 10, 0, 0), Quantity: 5}); err != nil {
125			t.Fatal(err)
126		}
127	
128		// 终止前最后一纳秒：2026-12-31 23:59:59.999999999 UTC。
129		lastNs := end.Add(-time.Nanosecond)
130		clk.t = lastNs
131		st, err := s.Status("u")
132		if err != nil {
133			t.Fatal(err)
134		}
135		if !st.Subscribed || st.CurrentTerms != wantTerms ||
136			st.ScheduledEnd == nil || !st.ScheduledEnd.Equal(end) {
137			t.Fatalf("status one ns before end = %+v, want subscribed with terms %+v and end %v",
138				st, wantTerms, end)
139		}
140		// 同一纳秒换 -05:00 表达（本地 2026-12-31 18:59:59.999999999），
141		// 订阅仍显示有效并展示终止安排。
142		clk.t = lastNs.In(zoneMinus5)
143		st, err = s.Status("u")
144		if err != nil {
145			t.Fatal(err)
146		}
147		if !st.Subscribed || st.ScheduledEnd == nil || !st.ScheduledEnd.Equal(end) {
148			t.Fatalf("status one ns before end in -05:00 = %+v, want subscribed with end %v", st, end)
149		}
150		clk.t = lastNs
151		// 该瞬间发生的事件仍属于十二月，十二月尚未出账，可以接收。
152		ev, err := s.RecordEvent(Event{AccountID: "u", EventID: "last-ns", At: lastNs, Quantity: 3})
153		if err != nil || !ev.Accepted || ev.Period != dec(2026) {
154			t.Fatalf("event one ns before end: %+v %v, want accepted in 2026-12", ev, err)
155		}
156		// 同一纳秒换 +08:00 表达（本地钟面已是 2027-01-01 07:59:59.999999999），
157		// 仍归十二月。
158		ev, err = s.RecordEvent(Event{
159			AccountID: "u", EventID: "last-ns-zoned",
160			At: lastNs.In(zonePlus8), Quantity: 1,
161		})
162		if err != nil || !ev.Accepted || ev.Period != dec(2026) {
163			t.Fatalf("zoned event one ns before end: %+v %v, want accepted in 2026-12", ev, err)
164		}
165	
166		// 恰到达终止瞬间：状态查询直接翻转——无有效订阅、当前套餐为零值、
167		// 不再展示终止安排；quiet 从未上报用量或生成账单，结果相同。
168		clk.t = end
169		for _, id := range []string{"u", "quiet"} {
170			st, err = s.Status(id)
171			if err != nil {
172				t.Fatal(err)
173			}
174			if st.Subscribed || st.CurrentTerms != (PlanTerms{}) ||
175				st.PendingChange != nil || st.ScheduledEnd != nil {
176				t.Fatalf("status of %s at end instant = %+v, want unsubscribed zero terms no schedule", id, st)
177			}
178		}
179	
180		// 恰在终止瞬间发生的新事件（不晚于提交时刻）：ErrEventBeforeSubscription。
181		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "at-end", At: end, Quantity: 1}); !errors.Is(err, ErrEventBeforeSubscription) {
182			t.Fatalf("event at end instant = %v, want ErrEventBeforeSubscription", err)
183		}
184		// 终止瞬间换 +08:00 表达（本地 2027-01-01 08:00），结果相同。
185		if _, err := s.RecordEvent(Event{
186			AccountID: "u", EventID: "at-end-zoned",
187			At: end.In(zonePlus8), Quantity: 1,
188		}); !errors.Is(err, ErrEventBeforeSubscription) {
189			t.Fatalf("zoned event at end instant = %v, want ErrEventBeforeSubscription", err)
190		}
191		// 被拒绝的事件不增加十二月累计，也不产生一月用量记录。
192		if u, _ := s.MonthlyUsage("u", dec(2026)); u.Total != 9 {
193			t.Fatalf("dec usage after rejected events = %d, want 9", u.Total)
194		}
195		if u, _ := s.MonthlyUsage("u", jan(2027)); u.Total != 0 {
196			t.Fatalf("jan usage after rejected events = %d, want 0", u.Total)
197		}
198		st, err = s.Status("u")
199		if err != nil {
200			t.Fatal(err)
201		}
202		if len(st.MonthlyUsage) != 1 || st.MonthlyUsage[0] != (Usage{Period: dec(2026), Total: 9}) {
203			t.Fatalf("monthly usage after rejected events = %+v, want only [2026-12 9]", st.MonthlyUsage)
204		}
205	
206		// 把终止瞬间换成其他时区表达，状态查询结果不变。
207		clk.t = end.In(zonePlus8)
208		st, err = s.Status("u")
209		if err != nil {
210			t.Fatal(err)
211		}
212		if st.Subscribed || st.CurrentTerms != (PlanTerms{}) || st.ScheduledEnd != nil {
213			t.Fatalf("status at end instant in +08:00 = %+v, want unsubscribed", st)
214		}
215		// 终止之后：此前接收的十二月用量仍可查询。
216		clk.t = utc(2027, 1, 10, 0, 0)
217		if u, _ := s.MonthlyUsage("u", dec(2026)); u.Total != 9 {
218			t.Fatalf("dec usage after end = %d, want 9", u.Total)
219		}
220		st, err = s.Status("u")
221		if err != nil {
222			t.Fatal(err)
223		}
224		if len(st.MonthlyUsage) != 1 || st.MonthlyUsage[0] != (Usage{Period: dec(2026), Total: 9}) {
225			t.Fatalf("history usage after end = %+v, want only [2026-12 9]", st.MonthlyUsage)
226		}
227	}
