21	// TestCancelSubscriptionScheduleEndAndStatus 覆盖终止时刻、重复取消不后移、
22	// 等待期与终止后的状态展示，以及当月完整计费、历史可查。
23	func TestCancelSubscriptionScheduleEndAndStatus(t *testing.T) {
24		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
25		mustPlan(t, s, planDef("a", 1000, 10, 10, 0))
26		mustAccount(t, s, "u")
27		mustSubscribe(t, s, "u", "a", utc(2026, 1, 1, 0, 0))
28	
29		// 终止时刻为请求时刻的下一个 UTC 自然月月初。
30		r := mustCancel(t, s, "u")
31		wantEnd := utc(2026, 2, 1, 0, 0)
32		if !r.Cancelled || !r.Cancellation.EndAt.Equal(wantEnd) {
33			t.Fatalf("cancel result = %+v, want end %v", r, wantEnd)
34		}
35		// 重复取消始终返回原终止时刻，不后移。
36		clk.t = utc(2026, 1, 20, 9, 0)
37		r2 := mustCancel(t, s, "u")
38		if r2.Cancelled || !r2.Cancellation.EndAt.Equal(wantEnd) {
39			t.Fatalf("repeat cancel = %+v, want same end %v", r2, wantEnd)
40		}
41	
42		// 等待取消期间仍显示有有效订阅，并展示终止时刻。
43		st, _ := s.Status("u")
44		if !st.Subscribed || st.ScheduledEnd == nil || !st.ScheduledEnd.Equal(wantEnd) {
45			t.Fatalf("status while cancelling: %+v", st)
46		}
47		if st.CurrentTerms.PlanID != "a" || st.PendingChange != nil {
48			t.Fatalf("terms/pending while cancelling: cur=%+v pending=%+v", st.CurrentTerms, st.PendingChange)
49		}
50	
51		// 当月照常接收用量。
52		clk.t = utc(2026, 1, 25, 12, 0)
53		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "j", At: utc(2026, 1, 25, 0, 0), Quantity: 15}); err != nil {
54			t.Fatalf("usage in cancellation month: %v", err)
55		}
56	
57		// 到达终止时刻：即使没有再上报用量或生成账单，也立即无有效订阅、无当前套餐、
58		// 无待切换、无终止安排。
59		clk.t = utc(2026, 2, 1, 0, 0)
60		st, _ = s.Status("u")
61		if st.Subscribed || st.CurrentTerms != (PlanTerms{}) || st.PendingChange != nil || st.ScheduledEnd != nil {
62			t.Fatalf("status at end: %+v", st)
63		}
64	
65		// 历史用量继续可查。
66		if u, _ := s.MonthlyUsage("u", jan(2026)); u.Total != 15 {
67			t.Fatalf("jan usage after end = %d", u.Total)
68		}
69		if len(st.MonthlyUsage) != 1 || st.MonthlyUsage[0].Period != jan(2026) {
70			t.Fatalf("history usage lost: %+v", st.MonthlyUsage)
71		}
72	
73		// 取消当月按完整月费与额度计费，不按天退款：
74		// fee 1000 + 超额 (15-10)*10 = 1500。
75		b := mustBill(t, s, "u", jan(2026))
76		if b.MonthlyFee != 1000 || b.OverageUnits != 5 || b.OverageFee != 50 || b.TotalDue != 1050 {
77			t.Fatalf("cancellation month bill not full terms: %+v", b)
78		}
79		// 历史账单在状态中继续可查。
80		st, _ = s.Status("u")
81		if len(st.Bills) != 1 || st.Bills[0].Period != jan(2026) {
82			t.Fatalf("history bills lost: %+v", st.Bills)
83		}
84	}
