	// 重报返回历史结果。
	r2, err := s.RecordPayment("a", "p1", jan(2026), 400)
	if err != nil || r2.Registered || r2.BillBalance != 600 || r2.Settled {
		t.Fatalf("replay: %+v %v", r2, err)
	}
}

