func TestSuspensionAndRecovery(t *testing.T) {
	s, clk := newTestService(utc(2026, 1, 20, 12, 0))
	mustPlan(t, s, Plan{ID: "p", MonthlyFee: 1000, IncludedUnits: 0, OveragePrice: 0, TaxRateBasisPoints: 0})
	mustAccount(t, s, "a")
	if err := s.Subscribe("a", "p", utc(2026, 1, 1, 0, 0)); err != nil {
		t.Fatal(err)
	}
	janEvent := Event{AccountID: "a", EventID: "j1", At: utc(2026, 1, 20, 0, 0), Quantity: 1}
	if _, err := s.RecordEvent(janEvent); err != nil {
		t.Fatal(err)
	}

	clk.t = utc(2026, 2, 1, 0, 0)
	if _, err := s.CreateBill("a", jan(2026)); err != nil {
		t.Fatal(err)
	}

	// 截止前正常接收 2 月用量。
	clk.t = utc(2026, 2, 2, 0, 0)
	febEvent := Event{AccountID: "a", EventID: "f1", At: utc(2026, 2, 2, 0, 0), Quantity: 1}
	if _, err := s.RecordEvent(febEvent); err != nil {
		t.Fatalf("event before due: %v", err)
	}

	// 到达截止时刻仍有余额：停用。
	clk.t = utc(2026, 2, 8, 0, 0)
	st, _ := s.Status("a")
	if !st.Suspended {
		t.Fatalf("should be suspended: %+v", st)
	}
	if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "f2", At: utc(2026, 2, 3, 0, 0), Quantity: 1}); !errors.Is(err, ErrSuspended) {
		t.Fatalf("new event while suspended: %v", err)
	}
	// 已接收事件的相同重报仍成功。
	if r, err := s.RecordEvent(janEvent); err != nil || r.Accepted {
		t.Fatalf("jan replay suspended: %+v %v", r, err)
	}
	if r, err := s.RecordEvent(febEvent); err != nil || r.Accepted {
		t.Fatalf("feb replay suspended: %+v %v", r, err)
	}

	// 部分付款仍欠费，继续停用。
	if _, err := s.RecordPayment("a", "p1", jan(2026), 500); err != nil {
		t.Fatal(err)
	}
	if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "f3", At: utc(2026, 2, 3, 0, 0), Quantity: 1}); !errors.Is(err, ErrSuspended) {
		t.Fatalf("still suspended after partial pay: %v", err)
	}

	// 结清后立即恢复；2 月账单尚未生成，新用量可继续累计。
	if _, err := s.RecordPayment("a", "p2", jan(2026), 500); err != nil {
		t.Fatal(err)
	}
	st, _ = s.Status("a")
	if st.Suspended {
		t.Fatalf("should resume: %+v", st)
	}
	if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "f3", At: utc(2026, 2, 3, 0, 0), Quantity: 1}); err != nil {
		t.Fatalf("event after resume: %v", err)
	}
	if u, _ := s.MonthlyUsage("a", feb(2026)); u.Total != 2 {
		t.Fatalf("feb usage = %d want 2", u.Total)
	}

	// Status 中应能看到各月用量与账单余额。
	if len(st.MonthlyUsage) != 2 || st.MonthlyUsage[0].Period != jan(2026) || st.MonthlyUsage[1].Period != feb(2026) {
		t.Fatalf("monthly usage: %+v", st.MonthlyUsage)
	}
	if len(st.Bills) != 1 || st.Bills[0].Period != jan(2026) || st.Bills[0].Balance != 0 || !st.Bills[0].Settled {
		t.Fatalf("bills: %+v", st.Bills)
	}
}

func TestOverflowLeavesNoTrace(t *testing.T) {
	s, clk := newTestService(utc(2026, 2, 1, 0, 0))
	mustPlan(t, s, Plan{ID: "p", MonthlyFee: 0, IncludedUnits: 0, OveragePrice: 1, TaxRateBasisPoints: 0})
	mustAccount(t, s, "a")
	if err := s.Subscribe("a", "p", utc(2026, 1, 1, 0, 0)); err != nil {
		t.Fatal(err)
	}

	base := maxInt64 - 5
	if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "base", At: utc(2026, 1, 10, 0, 0), Quantity: base}); err != nil {
		t.Fatal(err)
	}
	// 本次累计将溢出：失败且不消耗事件标识。
	if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "try", At: utc(2026, 1, 11, 0, 0), Quantity: 6}); !errors.Is(err, ErrOverflow) {
		t.Fatalf("usage overflow: %v", err)
	}
	if u, _ := s.MonthlyUsage("a", jan(2026)); u.Total != base {
		t.Fatalf("usage after overflow = %d", u.Total)
	}
	// 同一标识以不溢出的数量重试，应当成功。
	if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "try", At: utc(2026, 1, 11, 0, 0), Quantity: 5}); err != nil {
		t.Fatalf("id reused after overflow failure: %v", err)
	}

	// 超额费用溢出：超额用量 maxInt64 * 单价 2。
	mustAccount(t, s, "b")
	mustPlan(t, s, Plan{ID: "p2", MonthlyFee: 0, IncludedUnits: 0, OveragePrice: 2, TaxRateBasisPoints: 0})
	if err := s.Subscribe("b", "p2", utc(2026, 1, 1, 0, 0)); err != nil {
		t.Fatal(err)
	}
	if _, err := s.RecordEvent(Event{AccountID: "b", EventID: "big", At: utc(2026, 1, 10, 0, 0), Quantity: maxInt64}); err != nil {
		t.Fatal(err)
	}
	if _, err := s.CreateBill("b", jan(2026)); !errors.Is(err, ErrOverflow) {
		t.Fatalf("overage overflow: %v", err)
	}
	if _, err := s.GetBill("b", jan(2026)); !errors.Is(err, ErrBillNotFound) {
		t.Fatalf("partial bill left behind: %v", err)
	}

	// 税额与月费之和溢出（月费 maxInt64，税率 100%）。
	mustAccount(t, s, "c")
	mustPlan(t, s, Plan{ID: "p3", MonthlyFee: maxInt64, IncludedUnits: 0, OveragePrice: 0, TaxRateBasisPoints: 10000})
	if err := s.Subscribe("c", "p3", utc(2026, 1, 1, 0, 0)); err != nil {
		t.Fatal(err)
	}
	if _, err := s.CreateBill("c", jan(2026)); !errors.Is(err, ErrOverflow) {
		t.Fatalf("total overflow: %v", err)
	}

	_ = clk
}

func TestConcurrentDuplicates(t *testing.T) {
	s, clk := newTestService(utc(2026, 2, 1, 0, 0))
	mustPlan(t, s, Plan{ID: "p", MonthlyFee: 1000, IncludedUnits: 5, OveragePrice: 10, TaxRateBasisPoints: 1000})
	mustAccount(t, s, "a")
	if err := s.Subscribe("a", "p", utc(2026, 1, 1, 0, 0)); err != nil {
		t.Fatal(err)
	}
	ev := Event{AccountID: "a", EventID: "dup", At: utc(2026, 1, 10, 0, 0), Quantity: 7}

	const n = 64
	var wg sync.WaitGroup
	var accepted int64
	var mu sync.Mutex
	wg.Add(n)
	for i := 0; i < n; i++ {
		go func() {
			defer wg.Done()
			r, err := s.RecordEvent(ev)
			if err != nil {
				t.Errorf("concurrent event: %v", err)
				return
			}
			if r.Accepted {
				mu.Lock()
				accepted++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	if accepted != 1 {
		t.Fatalf("accepted = %d, want 1", accepted)
	}
	if u, _ := s.MonthlyUsage("a", jan(2026)); u.Total != 7 {
		t.Fatalf("usage = %d, want 7", u.Total)
	}

	// 并发出账只生成一张。
	bills := make([]Bill, n)
	wg.Add(n)
	for i := 0; i < n; i++ {
		go func(i int) {
			defer wg.Done()
			b, err := s.CreateBill("a", jan(2026))
			if err != nil {
				t.Errorf("concurrent bill: %v", err)
				return
			}
			bills[i] = b
		}(i)
	}
	wg.Wait()
	var due int64 = -1
	for _, b := range bills {
		if due == -1 {
			due = b.TotalDue
		} else if b.TotalDue != due {
			t.Fatalf("bills differ: %d vs %d", due, b.TotalDue)
		}
	}
	// fee 1000 + overage (7-5)*10=20 => subtotal 1020, tax 102 => 1122
	if due != 1122 {
		t.Fatalf("due = %d, want 1122", due)
	}

	// 并发同标识付款只扣一次。
	var registered int64
	wg.Add(n)
	for i := 0; i < n; i++ {
		go func() {
			defer wg.Done()
			r, err := s.RecordPayment("a", "pay", jan(2026), 1122)
			if err != nil {
				t.Errorf("concurrent pay: %v", err)
				return
			}
			if r.Registered {
				mu.Lock()
				registered++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	if registered != 1 {
		t.Fatalf("registered = %d, want 1", registered)
	}
	b, _ := s.GetBill("a", jan(2026))
	if b.Paid != 1122 || b.Balance != 0 || !b.Settled {
		t.Fatalf("bill after concurrent pay: paid=%d bal=%d settled=%v", b.Paid, b.Balance, b.Settled)
	}

	// 并发不同标识事件全部累计一次。
	wg.Add(n)
	for i := 0; i < n; i++ {
		go func(i int) {
			defer wg.Done()
			_, err := s.RecordEvent(Event{
				AccountID: "a",
				EventID:   fmt.Sprintf("e%d", i),
				At:        utc(2026, 2, 1, 0, 0),
				Quantity:  1,
			})
			if err != nil {
				t.Errorf("distinct event: %v", err)
			}
		}(i)
	}
	wg.Wait()
	if u, _ := s.MonthlyUsage("a", feb(2026)); u.Total != n {
		t.Fatalf("feb usage = %d, want %d", u.Total, n)
	}

	_ = clk
}

package meter_test

import (
	"errors"
	"fmt"
	"time"

	"github.com/descikazuyq/subscription-meter/meter"
)

// ExampleService_cancelSubscription 演示按月取消订阅的完整过程：登记取消、
// 等待终止期间的状态与用量接收、到达终止时刻后的状态翻转，以及取消当月的
// 出账。
//
// 账户 acct-cancel 2026-01-01 00:00 UTC 开通 plan-a（月费 1000 分、包含
// 10 单位、超额单价 100 分、税率 10%），没有欠费。2026-01-15 登记取消，
// 终止时刻为请求时刻的下一个 UTC 自然月月初零点：2026-02-01 00:00 UTC。
// 等待期间查询仍显示订阅有效、保留原套餐条件并展示终止时刻；再次取消返回
// 原终止时刻（Cancelled=false），不是失败，也不后移期限。登记取消后一月
// 用量照常接收，累计 15 单位。到达 2026-02-01 00:00 UTC 后直接查询即显示
// 订阅已终止、当前套餐为空、不再展示终止安排，无须先上报用量或生成账单。
// 为一月出账：仍收完整月费、给完整额度，用量 15、超额费用 500 分、税额
// 150 分、应付 1650 分，付款截止仍为 2026-02-08 00:00 UTC；取消不按天
// 退款、不免除应付款项、不自动生成账单，历史用量与账单继续可查。
//
// 示例还展示两处边界：提前登记但尚未到实际开通时刻的订阅不能取消
// （ErrSubscriptionNotActivated）；没有重新开通时，恰在终止时刻发生的新
// 用量不属于旧订阅，被拒绝（ErrEventBeforeSubscription）且不增加累计。
//
// 示例通过 NewServiceWithClock 注入可推进的时钟，输出不依赖运行当天日期。
func ExampleService_cancelSubscription() {
	const accountID = "acct-cancel"
	jan := meter.MonthOf(mustParseTime("2026-01-01T00:00:00Z"))
	feb := meter.MonthOf(mustParseTime("2026-02-01T00:00:00Z"))

	// 可推进的时钟：初始当前时刻为 2026-01-15 12:00 UTC（一月中旬），
	// 之后逐段推进到二月，复制后在任何真实日期运行结果都相同。
	now := mustParseTime("2026-01-15T12:00:00Z")
	s := meter.NewServiceWithClock(func() time.Time { return now })

	if err := s.CreateAccount(accountID); err != nil {
		panic(err)
	}
	// 套餐 plan-a：月费 1000 分、包含 10 单位、超额单价 100 分、税率 10%。
	if err := s.CreatePlan(meter.Plan{
		ID: "plan-a", MonthlyFee: 1000, IncludedUnits: 10,
		OveragePrice: 100, TaxRateBasisPoints: 1000,
	}); err != nil {
		panic(err)
	}
	// 账户 2026-01-01 00:00 UTC 开通，当前无欠费。
	if err := s.Subscribe(accountID, "plan-a", mustParseTime("2026-01-01T00:00:00Z")); err != nil {
		panic(err)
	}

	// 1 月 15 日登记按月取消：终止时刻为请求时刻的下一个 UTC 自然月
	// 月初零点，即 2026-02-01 00:00 UTC。
	r, err := s.CancelSubscription(accountID)
	if err != nil {
		panic(err)
	}
	fmt.Printf("cancel      cancelled=%t endAt=%s\n",
		r.Cancelled, r.Cancellation.EndAt.Format(time.RFC3339))

	// 登记取消后、到达终止时刻前：查询仍显示订阅有效、保留原套餐条件，
	// 并展示已安排的终止时刻。
	st, err := s.Status(accountID)
	if err != nil {
		panic(err)
	}
	fmt.Printf("status      subscribed=%t current=%s monthlyFee=%d scheduledEnd=%s\n",
		st.Subscribed, st.CurrentTerms.PlanID, st.CurrentTerms.MonthlyFee,
		st.ScheduledEnd.Format(time.RFC3339))

	// 等待终止期间再次取消：本次没有新建安排（Cancelled=false），仍返回
	// 原终止时刻。这不是取消失败，也不会把期限后移。
	now = mustParseTime("2026-01-20T09:00:00Z")
	r, err = s.CancelSubscription(accountID)
	if err != nil {
		panic(err)
	}
	fmt.Printf("recancel    cancelled=%t endAt=%s\n",
		r.Cancelled, r.Cancellation.EndAt.Format(time.RFC3339))

	// 取消登记后仍能接收一月的用量：一月累计达到 15 单位。
	now = mustParseTime("2026-01-25T12:00:00Z")
	ev, err := s.RecordEvent(meter.Event{
		AccountID: accountID, EventID: "e-jan",
		At: mustParseTime("2026-01-25T00:00:00Z"), Quantity: 15,
	})
	if err != nil {
		panic(err)
	}
	fmt.Printf("event e-jan accepted=%t period=%s\n", ev.Accepted, ev.Period)

	usage, err := s.MonthlyUsage(accountID, jan)
	if err != nil {
		panic(err)
	}
	fmt.Printf("usage       period=%s total=%d\n", usage.Period, usage.Total)

	// 终止时刻按请求时刻所在的 UTC 自然月计算，不能按调用者看到的本地
	// 月份解释：当前时刻用 UTC+8 表示为 2026-02-01 07:30（本地钟面已
	// 跨入二月），实际仍是 UTC 2026-01-31 23:30，终止时刻仍取 UTC
	// 一月的下一月月初 2026-02-01 00:00 UTC，而不是按本地二月再往后
	// 推一个月。
	plus8 := time.FixedZone("UTC+8", 8*60*60)
	now = time.Date(2026, time.February, 1, 7, 30, 0, 0, plus8)
	if err := s.CreateAccount("acct-tz"); err != nil {
		panic(err)
	}
	if err := s.Subscribe("acct-tz", "plan-a", mustParseTime("2026-01-01T00:00:00Z")); err != nil {
		panic(err)
	}
	r, err = s.CancelSubscription("acct-tz")
	if err != nil {
		panic(err)
	}
	fmt.Printf("cancel tz+8 local=%s endAt=%s\n",
		now.Format("2006-01-02 15:04 -0700"), r.Cancellation.EndAt.Format(time.RFC3339))

	// 推进到 2026-02-01 00:00 UTC（终止时刻）：直接查询即显示订阅已
	// 终止、当前套餐为空、不再展示终止安排，无须先上报用量或生成账单。
	now = mustParseTime("2026-02-01T00:00:00Z")
	st, err = s.Status(accountID)
	if err != nil {
		panic(err)
	}
	fmt.Printf("status      subscribed=%t currentPlan=%q scheduledEnd=%v\n",
		st.Subscribed, st.CurrentTerms.PlanID, st.ScheduledEnd)

	// 取消不会自动生成账单：一月账期虽已结束，尚未出账。
	_, err = s.GetBill(accountID, jan)
	fmt.Printf("get bill jan errBillNotFound=%t\n", errors.Is(err, meter.ErrBillNotFound))

	// 没有重新开通时，恰在终止时刻发生的新用量不属于旧订阅：被拒绝
	// （ErrEventBeforeSubscription），不增加累计。
	_, err = s.RecordEvent(meter.Event{
		AccountID: accountID, EventID: "e-at-end",
		At: mustParseTime("2026-02-01T00:00:00Z"), Quantity: 1,
	})
	fmt.Printf("event e-at-end errEventBeforeSubscription=%t\n",
		errors.Is(err, meter.ErrEventBeforeSubscription))

	// 被拒绝的事件没有累计：一月仍是 15，二月为零。
	usage, err = s.MonthlyUsage(accountID, jan)
	if err != nil {
		panic(err)
	}
	fmt.Printf("usage       period=%s total=%d\n", usage.Period, usage.Total)
	usage, err = s.MonthlyUsage(accountID, feb)
	if err != nil {
		panic(err)
	}
	fmt.Printf("usage       period=%s total=%d\n", usage.Period, usage.Total)

	// 为一月出账：取消当月仍收完整月费、提供完整额度，不按天退款。
	// 用量 15，超额 5 × 100 = 500 分；税 (1000+500) × 10% = 150 分；
	// 应付 1650 分。付款截止仍为账期结束后七天，即 2026-02-08 00:00
	// UTC，取消不会免除应付款项。
	janBill, err := s.CreateBill(accountID, jan)
	if err != nil {
		panic(err)
	}
	fmt.Printf("bill jan    plan=%s totalUsage=%d monthlyFee=%d includedUnits=%d overageUnits=%d overageFee=%d tax=%d totalDue=%d dueAt=%s\n",
		janBill.Terms.PlanID, janBill.TotalUsage, janBill.MonthlyFee,
		janBill.IncludedUnits, janBill.OverageUnits, janBill.OverageFee,
		janBill.Tax, janBill.TotalDue, janBill.DueAt.Format(time.RFC3339))

	// 订阅终止后历史账单仍然可查：应付与余额保持原样。
	janAgain, err := s.GetBill(accountID, jan)
	if err != nil {
		panic(err)
	}
	fmt.Printf("get bill jan plan=%s totalUsage=%d totalDue=%d balance=%d settled=%t\n",
		janAgain.Terms.PlanID, janAgain.TotalUsage, janAgain.TotalDue,
		janAgain.Balance, janAgain.Settled)

	// 边界一：提前登记但尚未到实际开通时刻的订阅不能取消。当前时刻为
	// 2026-02-01 00:00 UTC，acct-future 的开通时刻登记为 2 月 10 日，
	// 取消请求返回订阅尚未生效的错误。
	if err := s.CreateAccount("acct-future"); err != nil {
		panic(err)
	}
	if err := s.Subscribe("acct-future", "plan-a", mustParseTime("2026-02-10T00:00:00Z")); err != nil {
		panic(err)
	}
	_, err = s.CancelSubscription("acct-future")
	fmt.Printf("cancel future errSubscriptionNotActivated=%t\n",
		errors.Is(err, meter.ErrSubscriptionNotActivated))

	// Output:
	// cancel      cancelled=true endAt=2026-02-01T00:00:00Z
	// status      subscribed=true current=plan-a monthlyFee=1000 scheduledEnd=2026-02-01T00:00:00Z
	// recancel    cancelled=false endAt=2026-02-01T00:00:00Z
	// event e-jan accepted=true period=2026-01
	// usage       period=2026-01 total=15
	// cancel tz+8 local=2026-02-01 07:30 +0800 endAt=2026-02-01T00:00:00Z
	// status      subscribed=false currentPlan="" scheduledEnd=<nil>
	// get bill jan errBillNotFound=true
	// event e-at-end errEventBeforeSubscription=true
	// usage       period=2026-01 total=15
	// usage       period=2026-02 total=0
