52	// setupIndependenceFixture 建立带两个月用量、两张账单并已登记按月取消的
53	// 账户，结束时时钟停在 2026-03-05（等待取消期间，原定 4/1 终止）。
54	//
55	//	套餐 a：月费 1000、额度 10、超额单价 100、税率 0。
56	//	第一段订阅 1/1 开通、3/1 终止：1 月用量 12（账单 1200）、
57	//	2 月用量 30（账单 3000）；一月账单在 3/1 出账后当场付清，
58	//	二月账单未付（截止日 3/8，3/5 时尚未欠费停用）。
59	//	3/1 重新开通同一套餐，3/2 登记按月取消：当前订阅 4/1 终止。
60	//
61	// 返回服务、可调时钟与原定终止时刻。
62	func setupIndependenceFixture(t *testing.T) (*Service, *fakeClock, time.Time) {
63		t.Helper()
64		s, clk := newTestService(utc(2026, 1, 20, 12, 0))
65		mustPlan(t, s, planDef("a", 1000, 10, 100, 0))
66		mustAccount(t, s, "u")
67		mustSubscribe(t, s, "u", "a", utc(2026, 1, 1, 0, 0))
68		mustRecordEvent(t, s, Event{AccountID: "u", EventID: "e-jan", At: utc(2026, 1, 20, 0, 0), Quantity: 12})
69	
70		clk.t = utc(2026, 2, 15, 12, 0)
71		mustCancel(t, s, "u") // 第一段订阅 3/1 终止；2 月仍整月有效。
72		clk.t = utc(2026, 2, 20, 12, 0)
73		mustRecordEvent(t, s, Event{AccountID: "u", EventID: "e-feb", At: utc(2026, 2, 20, 0, 0), Quantity: 30})
74	
75		// 到达 3/1：第一段订阅终止，为一、二月出账并当场付清一月账单。
76		clk.t = utc(2026, 3, 1, 0, 0)
77		janBill := mustBill(t, s, "u", jan(2026))
78		if janBill.TotalDue != 1200 {
79			t.Fatalf("jan bill total = %d, want 1200", janBill.TotalDue)
80		}
81		febBill := mustBill(t, s, "u", feb(2026))
