83			t.Fatalf("feb bill total = %d, want 3000", febBill.TotalDue)
84		}
85		if _, err := s.RecordPayment("u", "pay-jan", jan(2026), janBill.TotalDue); err != nil {
86			t.Fatalf("pay jan bill: %v", err)
87		}
