89		// 同一时刻重新开通，3/2 登记按月取消，4/1 终止。
90		mustSubscribe(t, s, "u", "a", utc(2026, 3, 1, 0, 0))
91		clk.t = utc(2026, 3, 2, 12, 0)
92		r := mustCancel(t, s, "u")
