265			t.Fatalf("jan bill mixed terms: %+v", janBill)
266		}
267		// 截止前结清一月账单，避免欠费停用阻止二月用量。
268		if _, err := s.RecordPayment("u", "pay-jan", jan(2026), janBill.TotalDue); err != nil {
269			t.Fatal(err)
270		}
271	
272		// 二月用量 25 单位，发生在乙生效后的订阅期间、账户未停用。
273		clk.t = utc(2026, 2, 10, 12, 0)
274		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "e-feb", At: utc(2026, 2, 10, 0, 0), Quantity: 25}); err != nil {
275			t.Fatal(err)
276		}
277	
278		// 二月账期结束后出账；时钟用 -05:00 表示（本地 2026-02-28 19:00，
279		// 即 2026-03-01 00:00 UTC）。账单必须采用二月的乙条件：
280		// 月费 2000、超额 5×200=1000、税 0，应付 3000。
281		clk.t = time.Date(2026, time.February, 28, 19, 0, 0, 0, zoneMinus5)
282		if !clk.t.UTC().Equal(utc(2026, 3, 1, 0, 0)) {
283			t.Fatalf("billing clock = %v, want 2026-03-01 00:00 UTC", clk.t.UTC())
284		}
285		febBill, err := s.CreateBill("u", feb(2026))
286		if err != nil {
287			t.Fatalf("create feb bill: %v", err)
288		}
289		if febBill.Terms != termsOf(planYi) ||
290			febBill.TotalUsage != 25 || febBill.IncludedUnits != 20 ||
291			febBill.OverageUnits != 5 || febBill.MonthlyFee != 2000 ||
292			febBill.OverageFee != 1000 || febBill.Tax != 0 || febBill.TotalDue != 3000 {
293			t.Fatalf("feb bill mixed terms: %+v", febBill)
294		}
295	
296		// 一月账单的条件、用量与金额不因二月出账或切换生效而变化。
297		gotJan, err := s.GetBill("u", jan(2026))
298		if err != nil {
299			t.Fatal(err)
300		}
301		if gotJan.Terms != termsOf(planJia) || gotJan.TotalUsage != 15 || gotJan.TotalDue != 1500 {
